<?php

namespace App\Policies;

use App\Models\Reminder;
use App\Models\User;

class ReminderPolicy
{
    /**
     * Determine whether the user can list reminders.
     */
    public function viewAny(User $user): bool
    {
        return $user->can('reminders.view');
    }

    /**
     * Determine whether the user can view a reminder.
     */
    public function view(User $user, Reminder $reminder): bool
    {
        return $user->can('reminders.view');
    }

    /**
     * Reminders are generated by the system.
     */
    public function create(User $user): bool
    {
        return false;
    }

    /**
     * Determine whether the user can mark a reminder as handled.
     */
    public function update(User $user, Reminder $reminder): bool
    {
        return $user->can('reminders.update');
    }

    /**
     * Reminders keep their history and are not deleted.
     */
    public function delete(User $user, Reminder $reminder): bool
    {
        return false;
    }

    /**
     * Determine whether the user can restore a reminder.
     */
    public function restore(User $user, Reminder $reminder): bool
    {
        return false;
    }

    /**
     * Determine whether the user can permanently delete a reminder.
     */
    public function forceDelete(User $user, Reminder $reminder): bool
    {
        return false;
    }
}
